import heapq
from math import inf

class Solution:
    def minimumWeight(self, n: int, edges: List[List[int]], src1: int, src2: int, dest: int) -> int:
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w))

        def dijkstra(start, target):
            dist = [inf] * n
            dist[start] = 0
            pq = [(0, start)]
            while pq:
                d, u = heapq.heappop(pq)
                if u == target:
                    return d
                if d > dist[u]:
                    continue
                for v, w in g[u]:
                    if d + w < dist[v]:
                        dist[v] = d + w
                        heapq.heappush(pq, (dist[v], v))
            return inf

        best = inf
        for v in range(n):
            a, b, c = dijkstra(src1, v), dijkstra(src2, v), dijkstra(v, dest)
            if a != inf and b != inf and c != inf:
                best = min(best, a + b + c)
        return best if best != inf else -1

