class Solution {
    @SuppressWarnings("unchecked")
    public long minimumWeight(int n, int[][] edges, int src1, int src2, int dest) {
        List<int[]>[] g = new List[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) g[e[0]].add(new int[]{e[1], e[2]});
        long best = Long.MAX_VALUE;
        for (int v = 0; v < n; v++) {
            long a = dijkstra(g, src1, v, n);
            long b = dijkstra(g, src2, v, n);
            long c = dijkstra(g, v, dest, n);
            if (a != Long.MAX_VALUE && b != Long.MAX_VALUE && c != Long.MAX_VALUE)
                best = Math.min(best, a + b + c);
        }
        return best == Long.MAX_VALUE ? -1 : best;
    }

    private long dijkstra(List<int[]>[] g, int start, int target, int n) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{0L, start});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0];
            int u = (int) top[1];
            if (u == target) return d;
            if (d > dist[u]) continue;
            for (int[] e : g[u]) {
                long nd = d + e[1];
                if (nd < dist[e[0]]) {
                    dist[e[0]] = nd;
                    pq.offer(new long[]{nd, e[0]});
                }
            }
        }
        return Long.MAX_VALUE;
    }
};

