  for (const [u, v, w] of edges) g[u].push([v, w]);
  const INF = Infinity;
  const dijkstra = (start, target) => {
    const dist = new Array(n).fill(INF);
    dist[start] = 0;
    const heap = [[0, start]];
    const push = (node) => {
      heap.push(node);
      let i = heap.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heap[p][0] <= heap[i][0]) break;
        [heap[p], heap[i]] = [heap[i], heap[p]];
        i = p;
      }
    };
    const pop = () => {
      const top = heap[0];
      const last = heap.pop();
      if (heap.length) {
        heap[0] = last;
        let i = 0;
        for (;;) {
          const l = 2 * i + 1, r = l + 1;
          let m = i;
          if (l < heap.length && heap[l][0] < heap[m][0]) m = l;
          if (r < heap.length && heap[r][0] < heap[m][0]) m = r;
          if (m === i) break;
          [heap[m], heap[i]] = [heap[i], heap[m]];
          i = m;
        }
      }
      return top;
    };
    while (heap.length) {
      const [d, u] = pop();
      if (u === target) return d;
      if (d > dist[u]) continue;
      for (const [v, w] of g[u]) {
        if (d + w < dist[v]) {
          dist[v] = d + w;
          push([dist[v], v]);
        }
      }
    }
    return INF;
  };
  let best = INF;
  for (let v = 0; v < n; v++) {
    const a = dijkstra(src1, v), b = dijkstra(src2, v), c = dijkstra(v, dest);
